class Solution:
    def kthCharacter(self, s: str, k: int) -> str:
        cursor = 0
        for i, w in enumerate(s.split(' ')):
            if i > 0:
                if k == cursor: return ' '
                cursor += 1
            L = len(w)
            block = L * (L + 1) // 2
            if k < cursor + block:
                off = k - cursor
                j = 0
                while (j + 1) * (j + 2) // 2 <= off:
                    j += 1
                return w[j]
            cursor += block
        return ''

