class Solution {
public:
    char kthCharacter(string s, long long k) {
        long long cursor = 0;
        stringstream ss(s);
        string w;
        bool first = true;
        while (ss >> w) {
            if (!first) {
                if (k == cursor) return ' ';
                cursor++;
            }
            first = false;
            long long L = w.size(), block = L * (L + 1) / 2;
            if (k < cursor + block) {
                long long off = k - cursor;
                int j = 0;
                while ((long long)(j+1)*(j+2)/2 <= off) j++;
                return w[j];
            }
            cursor += block;
        }
        return ' ';
    }
};

