class Solution {
    public char kthCharacter(String s, long k) {
        long cursor = 0;
        boolean first = true;
        for (String w : s.split(" ")) {
            if (!first) {
                if (k == cursor) return ' ';
                cursor++;
            }
            first = false;
            long L = w.length(), block = L * (L + 1) / 2;
            if (k < cursor + block) {
                long off = k - cursor;
                int j = 0;
                while ((long)(j+1)*(j+2)/2 <= off) j++;
                return w.charAt(j);
            }
            cursor += block;
        }
        return ' ';
    }
}

