var kthCharacter = function(s, k) {
    let cursor = 0;
    const words = s.split(' ');
    for (let i = 0; i < words.length; i++) {
        const w = words[i];
        if (i > 0) {
            if (k === cursor) return ' ';
            cursor++;
        }
        const L = w.length, block = L * (L + 1) / 2;
        if (k < cursor + block) {
            let off = k - cursor, j = 0;
            while ((j+1)*(j+2)/2 <= off) j++;
            return w[j];
        }
        cursor += block;
    }
    return '';
};
